// The note: the services' pro-rated spend while the room was open, labelled estimated and not the incident's extra
// cost, per service, with a link to Landledger's Explore. Posted as a room note, because the landfall plugin can't write
// a postmortem section. Money as Landledger posts it: to the cent, half away from zero, on the decimal (no float).
const w = $('Window and services').first().json;
const cost = $input.first().json;
const micros = (v) => {
  const m = /^(-)?(\d+)(?:\.(\d{1,6}))?$/.exec(String(v ?? '').trim());
  if (!m) return 0n;
  const x = BigInt(m[2]) * 1000000n + BigInt((m[3] ?? '').padEnd(6, '0'));
  return m[1] ? -x : x;
};
const usd = (x) => {
  const negative = x < 0n;
  const abs = negative ? -x : x;
  const cents = abs / 10000n + (abs % 10000n >= 5000n ? 1n : 0n);
  return `${negative && cents ? '-' : ''}$${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
};
const at = (iso) => new Date(iso).toISOString().slice(0, 16).replace('T', ' ');
const list = (xs) => (xs.length < 2 ? xs.join('') : `${xs.slice(0, -1).join(', ')} and ${xs.at(-1)}`);
const minutes = Math.round((Date.parse(w.to) - Date.parse(w.from)) / 60000);
const span = minutes >= 1440 ? `${Math.floor(minutes / 1440)} d ${Math.floor((minutes % 1440) / 60)} h` : minutes >= 60 ? `${Math.floor(minutes / 60)} h ${minutes % 60} min` : `${minutes} min`;
const window = `${at(w.from)} to ${at(w.to)} UTC (${span})`;
const services = cost.services ?? [];
const known = services.filter((s) => s.known);
const total = known.reduce((sum, s) => sum + micros(s.amount), 0n);
const lines = services.map((s) => (s.known ? `- ${s.service}: ${usd(micros(s.amount))}` : `- ${s.service}: no cost in Landledger under this name`));
// The 1st of a month: Landledger charges an invoice's lines that have no daily estimate on that day, whole, so a window
// over a 1st takes a share of a month's invoice, not only spend while the room was open. Said, with the amount.
const firsts = new Map();
for (const s of known) for (const d of s.days ?? []) if (/-01$/.test(String(d.day)) && micros(d.amount) !== 0n) firsts.set(d.day, (firsts.get(d.day) ?? 0n) + micros(d.amount));
const firstDays = [...firsts.keys()].sort();
const month = w.from.slice(0, 7);
const explore = `${w.consoleUrl}/explore?by=service&month=${month}&filter=${encodeURIComponent(w.services.map((s) => `service:${s}`).join(','))}`;
const text = [
  known.length
    ? `Pro-rated spend of these services during the incident (estimated), not the incident's extra cost: ${usd(total)} (USD), ${window}.`
    : `No matching services: cost unknown. Landledger has no cost under ${list(w.services)}, ${window}.`,
  ...lines,
  ...(known.length ? ["Estimated: each day's cost of these services in Landledger, by the share of the day inside the incident's window: what they cost while it was open, not what the incident added. Not an invoiced figure."] : []),
  ...(firstDays.length ? [`Of this, ${usd([...firsts.values()].reduce((a, b) => a + b, 0n))} falls on ${list(firstDays)}: Landledger charges invoice lines that have no daily estimate on the 1st of the month, so ${firstDays.length > 1 ? 'those days' : 'that day'} may hold part of a month's invoice rather than spend during the incident.`] : []),
  ...(Number(cost.chunks ?? 1) > 1 ? [`The window is longer than the 31 days Landledger answers at a time: it was asked in ${cost.chunks} parts and added up.`] : []),
  `Explore in Landledger: ${explore}`,
  `Posted by Landflow as a room note: it can't write a postmortem section.`,
].join('\n');
return { incidentId: w.incidentId, text, total: known.length ? cost.total : null, known: known.length, services: cost.services, from: w.from, to: w.to, explore, chunks: Number(cost.chunks ?? 1) };
